def solve_for_n(n):
    import numpy as np
    from scipy.optimize import minimize
    def objective(f):
        num = np.sum(f**2)
        den = np.sum(np.arange(1, n+1) * f**2)
        return -num / den
    cons = []
    for i in range(1, n-1):
        cons.append({'type': 'ineq', 'fun': lambda f, i=i: 2*f[i] - f[i-1] - f[i+1]})
    bounds = [(0, None) for _ in range(n)]
    best_r = -1
    for start_f in [np.ones(n), np.linspace(1, 0, n), np.linspace(0, 1, n)]:
        res = minimize(objective, start_f, method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            best_r = max(best_r, -res.fun)
    return best_r

for n in range(2, 13):
    print(f"n={n}: {solve_for_n(n)}")

