            f1 = x[0]
            d = x[1:]
            val = f1 + np.sum(d[:i-1])
            return val
        cons.append({'type': 'ineq', 'fun': f_func})

    best_s = 0
    best_f = None
    for start_point in [np.ones(n), np.array([1.0, 0.5, 0.5, 0.5]), np.array([1.0, 0.1, 0.1, 0.1]), np.array([1.0, -0.1, -0.1, -0.1]), np.random.rand(n) * 10]:
