import numpy as np
from scipy.optimize import minimize

def objective(f):
    n = len(f)
    num = np.sum(f**2)
    den = np.sum(np.arange(1, n + 1) * f**2)
    if den == 0:
        return 0
    return -num / den

def penalty_objective(f, n):
    # Sum f_i^2 / Sum i f_i^2
    res = objective(f)

    # Penalty for f_i < 0
    penalty = 0
    for x in f:
        if x < 0:
            penalty += (x**2) * 1e6

    # Penalty for f_{i+1} + f_{i-1} > 2f_i
    for i in range(1, n - 1):
        val = f[i+1] + f[i-1] - 2*f[i]
        if val > 0:
            penalty += (val**2) * 1e6

    return res + penalty

def solve_max_S_n_v8(n):
    best_s = 0
    for _ in range(50):
        start_point = np.random.rand(n) * 10
        res = minimize(lambda f: penalty_objective(f, n), start_point, method='Nelder-Mead')
        if -res.fun > best_s:
            best_s = -res.fun
    return best_s

for n in range(2, 11):
    print(f"n={n}, max S = {solve_max_S_n_v8(n)}")

